<?php
declare(strict_types=1);

require_once __DIR__.'/vendor/dompdf/dompdf/autoload.inc.php';

use Dompdf\Dompdf;
use Dompdf\Options;

function pdf_escape(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function pdf_money(mixed $value):string{return 'S/ '.number_format((float)$value,2,'.',',');}
function pdf_long_date(?string $value):string{$months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];try{$date=new DateTimeImmutable((string)$value);}catch(Throwable){$date=new DateTimeImmutable();}return $date->format('d').' de '.$months[(int)$date->format('n')-1].' de '.$date->format('Y');}
function pdf_image(string $file):string{$path=__DIR__.'/assets/documents/'.$file;if(!is_file($path))return '';return 'data:image/png;base64,'.base64_encode((string)file_get_contents($path));}

function agreement_html(array $d):string{
 $rows='';foreach(($d['cuotas']??[])as $index=>$quota){$rows.='<tr><td>'.sprintf('%02d',$index+1).'</td><td>'.pdf_escape((new DateTimeImmutable($quota['fecha']))->format('d/m/Y')).'</td><td>'.pdf_money($quota['monto']).'</td></tr>';}
 $form=$d['tipo_acuerdo']==='CANCELACION'?'CANCELACIÓN TOTAL':'CONVENIO';$logo=pdf_image('Acuerdo_de_Pago_image2.png');$banner=pdf_image('Acuerdo_de_Pago_image1.png');$signature=pdf_image('Acuerdo_de_Pago_image4.png');
 return '<!doctype html><html><head><meta charset="utf-8"><style>'.pdf_css().'</style></head><body class="agreement"><img class="top-banner" src="'.$banner.'"><header class="doc-header"><img src="'.$logo.'"><h1>ACUERDO DE PAGO EXCEPCIONAL</h1></header><p class="right">Lima, '.pdf_long_date($d['fecha_documento']).'</p><p><b>Señor(a):</b> '.pdf_escape($d['nombre_completo']).'<br><b>Identificación:</b> '.pdf_escape($d['dni']).'<br><b>Teléfono:</b> '.pdf_escape($d['telefono']?:'-').'<br><b>Correo:</b> '.pdf_escape($d['correo']?:'-').'</p><p>Presente.-</p><p><b>Referencia: ACUERDO DE '.pdf_escape($form).'</b><br><b>Producto:</b> '.pdf_escape($d['producto']?:'TARJETA').'<br><b>OBLIGACIÓN N.º</b> '.pdf_escape($d['numero_operacion']).'</p><p>Estimado(a) señor(a):</p><p class="justify">Cordialmente y en relación con su solicitud para normalizar las obligaciones a su cargo citadas en la referencia, la cual fue cedida por Financiera Oh! a GRUPO INMOBILIARIO SYS S.A.C.; nos permitimos manifestarle que después de evaluar la propuesta, se autorizó el siguiente acuerdo de cancelación:</p><table><thead><tr><th>OBLIGACIÓN N.º</th><th>DEUDA TOTAL</th><th>MONTO DE CANCELACIÓN</th><th>CUOTAS N.º</th><th>FORMA DE PAGO</th></tr></thead><tbody><tr><td>'.pdf_escape($d['numero_operacion']).'</td><td>'.pdf_money($d['deuda_total']).'</td><td>'.pdf_money($d['monto_acordado']).'</td><td>'.sprintf('%02d',count($d['cuotas']??[])).'</td><td>'.pdf_escape($form).'</td></tr></tbody></table><table class="quota"><thead><tr><th>CUOTA</th><th>FECHA PAGO</th><th>VALOR</th></tr></thead><tbody>'.$rows.'</tbody></table><p class="note">(*) En caso de incumplimiento de las fechas e importes mencionados, la propuesta queda sin validez.</p><p class="justify">La anterior fórmula de pago no implica novación, reestructuración ni desistimiento de las acciones judiciales que se hayan iniciado para la recuperación de las sumas adeudadas; lo que indica que los valores antes mencionados son un mecanismo de facilidad de pago unilateral, brindado por GRUPO INMOBILIARIO SYS S.A.C., y en caso de incumplimiento de alguna de las facilidades de pago aquí establecidas se entenderá que el presente acuerdo no tiene ningún efecto y, por lo tanto, cualquier pago realizado se tendrá como un abono a la obligación y se aplicará conforme a los términos iniciales del crédito. Asimismo, la obligación continuará vencida y no habrá lugar a mejorar la calificación ante las centrales de riesgo hasta que se cumpla la presente facilidad de pago o se cancele totalmente la obligación.</p><div class="page-break"></div><p class="justify">Una vez cancelada la deuda de la referencia y verificado el pago en la cuenta de GRUPO INMOBILIARIO SYS S.A.C., se procederá a efectuar el cierre operativo y contable de la obligación y, en consecuencia, se expedirá al titular la respectiva constancia de no adeudo, la cual será generada por GRUPO INMOBILIARIO SYS S.A.C. y enviada al correo electrónico del cliente.</p><p class="justify">En caso se requiera la terminación de algún proceso o se solicite el levantamiento de cualquier medida cautelar iniciada por FINANCIERA OH!, los gastos y honorarios que estos generen serán asumidos por el titular de la deuda.</p><p class="justify">Este acuerdo no incluye los costos y costas que pudieran corresponder en caso de tener un proceso judicial activo por la obligación señalada.</p><p class="payment"><b>Los pagos deben realizarse en la CUENTA CORRIENTE BCP 1937221442057, RUC 20601193150, a nombre de GRUPO INMOBILIARIO SYS S.A.C.; o mediante Yape al 995485422 a nombre de la empresa.</b><br><br>Por Agentes BCP al N.º de cuenta 1937221442057 a nombre de GRUPO INMOBILIARIO S&amp;S S.A.C.</p><p>Las copias de cada consignación deben enviarse al correo <b>ssilupu@smainversiones.pe</b>. El cliente deberá conservar el físico de cada comprobante.</p><p>Cualquier inquietud adicional será atendida en el teléfono <b>987973372</b>.</p><p>Cordialmente.</p><div class="signature"><img src="'.$signature.'"><b>Shirley Silupú</b><span>Jefe de Cartera</span></div></body></html>';
}

function cesion_html(array $d):string{
 $logo=pdf_image('Cesion_Derechos_image2.png');$banner=pdf_image('Cesion_Derechos_image3.png');$signature=pdf_image('Cesion_Derechos_image1.png');$location=trim(implode(' - ',array_filter([$d['distrito']??null,$d['departamento']??null])));
 return '<!doctype html><html><head><meta charset="utf-8"><style>'.pdf_css().'</style></head><body class="cession"><div class="cession-head"><img class="finance-logo" src="'.$logo.'"><img class="finance-banner" src="'.$banner.'"></div><p class="right">Lima, '.pdf_long_date($d['fecha_documento']).'</p><p>Señor(a)(ita)</p><p><b>'.pdf_escape($d['nombre_completo']).'</b><br>DNI: '.pdf_escape($d['dni']).'<br>'.pdf_escape($d['direccion']?:'DIRECCIÓN NO REGISTRADA').'<br>'.pdf_escape($location).'</p><p><b>Referencia:</b> Tarjeta de Crédito N.º '.pdf_escape($d['numero_operacion']).'</p><p><b>Deuda Total: '.pdf_money($d['deuda_total']).'</b></p><p>De nuestra consideración:</p><p class="justify">Por medio de la presente nos dirigimos a usted para hacer de su conocimiento que, con fecha <b>23 de junio de 2025</b>, hemos celebrado un contrato de Cesión de Derechos con la empresa GRUPO INMOBILIARIO S &amp; S S.A.C., a través del cual hemos cedido en favor de dicha empresa, de forma incondicional e irrevocable, la deuda por consumos con Tarjeta de Crédito que usted mantiene con nosotros.</p><p class="justify">En atención a lo señalado líneas arriba, de conformidad con lo establecido en el artículo 1215.º del Código Civil, a partir de la fecha de recepción de la presente comunicación usted tendrá como acreedor de su deuda por consumos con Tarjeta de Crédito a la empresa GRUPO INMOBILIARIO S &amp; S S.A.C., con RUC N.º 20601193150, la cual lo(a) contactará a efectos de orientarlo(a) en el pago. También podrá coordinar dirigiéndose a sus oficinas ubicadas en Los Aromos 437, distrito de La Molina, Lima, de lunes a viernes de 09:00 a 17:00 horas; comunicándose al 987973372; escribiendo a ssilupu@smainversiones.pe; o visitando https://www.smainversiones.pe/.</p><p>Sin otro particular y agradeciendo la atención que brinde a la presente, nos suscribimos de usted.</p><p>Atentamente,</p><div class="signature finance-sign"><img src="'.$signature.'"><b>Diego Andrés Callirgos</b><span>Gerente de Riesgos y Cobranzas</span></div><p class="note">Nota: Si al recibir la presente comunicación usted ya realizó el pago de su deuda, agradecemos dirigirse a la dirección o teléfonos indicados a fin de dejar sin efecto la presente.</p></body></html>';
}

function pdf_css():string{return '@page{margin:15mm 16mm 16mm}body{font-family:"DejaVu Sans",sans-serif;color:#111;font-size:10.5px;line-height:1.45}p{margin:0 0 10px}.right{text-align:right}.justify{text-align:justify}.page-break{page-break-before:always}h1{font-size:15px;text-align:center;margin:12px 0 20px}.top-banner{width:100%;height:18px}.doc-header{margin:8px 0 12px}.doc-header img{width:126px}.doc-header h1{margin-top:-18px}table{width:100%;border-collapse:collapse;margin:13px 0;font-size:8.5px;page-break-inside:avoid}th,td{border:1px solid #333;padding:6px 4px;text-align:center}th{background:#0b3d35;color:#fff}.quota{width:72%;margin-left:auto;margin-right:auto}.quota th{background:#555}.note{font-size:8.5px}.payment{padding:8px;border:1px solid #999}.signature{width:210px;margin-top:18px;text-align:center}.signature img{display:block;max-width:95px;max-height:70px;margin:0 auto -4px}.signature span{display:block}.cession{font-family:Arial,"DejaVu Sans",sans-serif;font-size:10.5px}.cession-head{height:44px;margin-bottom:12px}.finance-logo{width:115px;margin-top:8px}.finance-banner{float:right;width:360px;margin-top:12px}.finance-sign img{max-width:70px;max-height:62px}';}

function render_document_pdf(string $type,array $data):string{
 $options=new Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('chroot',[__DIR__]);$options->set('defaultFont','DejaVu Sans');
 $dompdf=new Dompdf($options);$dompdf->setPaper('A4','portrait');$dompdf->loadHtml($type==='ACUERDO_PAGO'?agreement_html($data):cesion_html($data),'UTF-8');$dompdf->render();return $dompdf->output();
}

function generate_document_now(PDO $db,array $config,int $id):void{
 $q=$db->prepare("SELECT d.id,d.tipo,d.estado,d.storage_key,a.id acuerdo_id,COALESCE(a.fecha_acuerdo,CURDATE()) fecha_documento,COALESCE(a.tipo_acuerdo,'CANCELACION') tipo_acuerdo,COALESCE(a.saldo_negociado,o.saldo) deuda_total,COALESCE(a.monto_acordado,o.saldo) monto_acordado,COALESCE(a.monto_inicial,0) monto_inicial,c.nombre_completo,c.numero_documento dni,c.direccion,c.distrito,c.departamento,a.telefono_documento telefono,a.correo_documento correo,o.numero_operacion,o.producto FROM documentos d LEFT JOIN acuerdos a ON a.id=d.acuerdo_id JOIN clientes c ON c.id=COALESCE(d.cliente_id,a.cliente_id) JOIN operaciones o ON o.id=COALESCE(d.operacion_id,a.operacion_id) WHERE d.id=?");$q->execute([$id]);$data=$q->fetch();if(!$data)throw new RuntimeException('Documento no encontrado');if($data['estado']==='DISPONIBLE')return;
 $data['cuotas']=[];if($data['acuerdo_id']){$cq=$db->prepare('SELECT fecha_vencimiento fecha,monto FROM cuotas WHERE acuerdo_id=? ORDER BY numero_cuota');$cq->execute([$data['acuerdo_id']]);$data['cuotas']=$cq->fetchAll();}
 $db->prepare("UPDATE documentos SET estado='GENERANDO' WHERE id=?")->execute([$id]);
 try{$pdf=render_document_pdf($data['tipo'],$data);if(!str_starts_with($pdf,'%PDF-'))throw new RuntimeException('PDF inválido');$base=(string)($config['DOCUMENT_OUTPUT_PATH']??'');if($base===''||(!is_dir($base)&&!mkdir($base,0700,true)))throw new RuntimeException('Almacenamiento no disponible');$key=bin2hex(random_bytes(24)).'.pdf';if(file_put_contents(rtrim($base,'/\\').DIRECTORY_SEPARATOR.$key,$pdf,LOCK_EX)===false)throw new RuntimeException('No se pudo guardar el PDF');$db->prepare("UPDATE documentos SET estado='DISPONIBLE',storage_key=?,generado_at=NOW() WHERE id=?")->execute([$key,$id]);}catch(Throwable $e){$db->prepare("UPDATE documentos SET estado='ERROR' WHERE id=?")->execute([$id]);throw $e;}
}
